import {LEVELS,PATHS,challenge,levelById,nextLevel,sandbox} from './levels.js';
import {createWorld,applyCommand,assess,LIMITS,featureName} from './world.js';
import {runBlocks,pseudocode,BLOCK_LABELS} from './blocks.js';
import {Profiles,progress,recommend,validateBackup,BACKUP_MAX} from './profiles.js';
import {RuntimeHost,friendlyError} from './runtime-host.js';
import {icon,esc,atlas,MARKERS,worldSvg} from './scenery.js';
import {hero,robot} from './art.js';
import {ACTIVITIES,mountGame} from './games.js';

const app=document.querySelector('#app'),dialog=document.querySelector('#dialog');
const profiles=new Profiles();
let screen='map',path=profiles.current.lastPath,selected=recommend(profiles.current),config,saved,world;
let host=null,loadPromise=null,runBusy=false,tape=[],features=[],tapeIndex=0,runError='',autoTimer=null,gameCleanup=null,nextAfterGame=null,gameId=null;
let slot=[],selectedBlock=null,insertAt=null,viewEpoch=0,readingCode=false,speaking=false;
const $=s=>app.querySelector(s),copy=x=>JSON.parse(JSON.stringify(x));
const button=(action,label,ico='',className='',attrs='')=>`<button data-action="${action}" class="${className}" ${attrs}>${ico?icon(ico):''}<span>${label}</span></button>`;
function toast(text){const el=document.querySelector('#toast');el.textContent=text;el.classList.add('shown');setTimeout(()=>el.classList.remove('shown'),4000);}
function announce(text){document.querySelector('#announcer').textContent=text;}
function save(){if(saved&&config){try{profiles.save(config.id,saved);if(profiles.error)toast(profiles.error);}catch(e){toast(e.message);const previous=profiles.current.saved[config.id];if(previous)saved=copy(previous);}}}
function support(){return saved.exampleUsed?'example':saved.hintStage?'hints':'independent';}
function motionReduced(){return profiles.current.settings.reducedMotion||matchMedia('(prefers-reduced-motion: reduce)').matches;}
function applySettings(){document.documentElement.classList.toggle('large-text',profiles.current.settings.largeText);document.documentElement.classList.toggle('reduced-motion',motionReduced());}
function cleanup(){viewEpoch++;speaking=false;clearTimeout(autoTimer);autoTimer=null;host?.stop();host=null;loadPromise=null;gameCleanup?.();gameCleanup=null;runBusy=false;tape=[];features=[];tapeIndex=0;runError='';if('speechSynthesis'in window)speechSynthesis.cancel();}
function navigate(target,id){save();cleanup();screen=target;if(target==='mission'){openMission(id);return;}if(target==='game'){renderGame(id);return;}render();window.scrollTo({top:0,behavior:'instant'});$('#main')?.focus({preventScroll:true});}
function identity(){return '<span class="brand-shield" aria-hidden="true">✦</span><span class="brand-words">HERO ACADEMY<small>CodeQuest</small></span>';}
function header(){const p=profiles.current;return `<header class="topbar"><a href="#" data-action="map" class="brand" aria-label="Hero Academy CodeQuest home">${identity()}</a><div class="top-right"><span class="points" aria-label="${p.points} reward points">${icon('star')}<strong id="points-total">${p.points.toLocaleString('en-GB')}</strong><span class="points-label">points</span></span><button class="player-button" data-action="players">${icon('user')}<span>${esc(p.name)}</span><span class="chevron" aria-hidden="true">⌄</span></button></div></header>`;}
function nav(){return `<nav class="side-nav" aria-label="Main navigation">${[['map','Islands','map'],['sandbox','Playground','code'],['fun','Fun & games','game'],['hero','My hero','cape'],['adults','Grown-ups','gear']].map(([action,label,ico])=>button(action,label,ico,(screen===action||(action==='map'&&['mission','branch'].includes(screen)))?'active':'',screen===action?'aria-current="page"':'')).join('')}<div class="nav-bottom"><span class="nav-pip">${robot()}</span><span>Little steps.<br>Big possibilities.</span></div></nav>`;}
function shell(content){applySettings();app.innerHTML=`${header()}${nav()}<main id="main" tabindex="-1">${content}</main><footer>Hero Academy · Made for curious minds <span>Quiet play. Room to try.</span></footer>`;if(profiles.error)toast(profiles.error);}
function updateHeader(){const total=$('#points-total');if(total)total.textContent=profiles.current.points.toLocaleString('en-GB');}
function render(){if(screen==='map')renderMap();else if(screen==='branch')renderBranch();else if(screen==='hero')renderHero();else if(screen==='adults')renderAdults();else if(screen==='fun')renderFun();else if(screen==='sandbox')renderSandboxChoice();}
function renderMap(){
 const p=profiles.current,list=LEVELS.filter(l=>l.path===path);if(!levelById(selected)||levelById(selected).path!==path)selected=list.find(l=>!p.completed[l.id])?.id??list[0].id;
 const l=levelById(selected),index=list.findIndex(x=>x.id===selected),[hx,hy]=MARKERS[index],suggested=recommend(p),completed=progress(p,path);
 shell(`<div class="page-title"><div><span class="eyebrow">Your adventure, your way</span><h1>The islands need a hero.</h1><p>A little code can bring a whole world back to life.</p></div><span class="page-stamp">${icon('flag')} 30 coding missions<br><small>Every path is open</small></span></div>
 <div class="island-tabs" role="group" aria-label="Choose an island">${Object.entries(PATHS).map(([key,x])=>`<button data-action="path" data-path="${key}" class="island-tab ${key===path?'selected':''}" aria-pressed="${key===path}"><span class="island-tab-icon ${key}">${icon(key==='foundation'?'kit':key==='python'?'plant':'lamp')}</span><span><strong>${x.name}</strong><small>${x.tag}</small></span><span class="tab-progress">${progress(p,key)}<span>/10</span></span></button>`).join('')}</div>
 <section class="map-layout" aria-label="Adventure island"><div class="island-map"><div class="map-canvas">${atlas(path,p.completed)}<div class="map-markers">${list.map((level,i)=>{const [x,y]=MARKERS[i];return `<button class="map-marker ${p.completed[level.id]?'complete':''} ${selected===level.id?'current':''}" data-action="select-mission" data-id="${level.id}" style="left:${x/10}%;top:${y/4.9}%" aria-label="${level.id} ${esc(level.title)}${p.completed[level.id]?', completed':''}${suggested===level.id?', recommended':''}" aria-pressed="${selected===level.id}"><span>${p.completed[level.id]?icon('check'):(path==='foundation'?level.n:level.id)}</span>${suggested===level.id?'<i aria-hidden="true"></i>':''}</button>`;}).join('')}<span class="map-hero" style="left:${hx/10}%;top:${hy/4.9}%">${hero(p.appearance.suit,p.appearance.emblem,p.appearance.cape)}</span><button class="map-treasure ${p.collectibles.includes('treasure-'+path)?'found':''}" data-action="treasure" aria-label="Find an optional island treasure">${icon(p.collectibles.includes('treasure-'+path)?'check':'star')}</button></div></div><span class="map-caption">${icon('map')} Tap a place. Choose your adventure.</span></div>
 <aside class="quest-pick"><div class="pip-hello"><span>${robot()}</span><div><span class="eyebrow">${suggested===l.id?'Pip’s pick':'Let’s explore'}</span><strong>We can help!</strong></div></div><span class="mission-tag">${l.id} · ${l.concept}</span><h2>${l.title}</h2><p>${l.task}</p><div class="pick-pictures">${icon(path==='foundation'?'robot':'code')}<span>→</span>${icon(l.kind==='garden'?'plant':l.kind==='message'?'signal':'spark')}</div>${button('open-selected','Let’s go','play','orange')}<p class="small quiet">${path==='foundation'?'Picture blocks. No typing needed.':path==='python'?'Real Python. Try your own ideas.':'Real C#. Build something helpful.'}</p><div class="island-progress"><div><strong>${completed} / 10</strong><span>places restored</span></div><progress max="10" value="${completed}" aria-label="${completed} of 10 ${PATHS[path].name} missions completed"></progress></div></aside></section>
 <div class="map-bottom"><div class="note-pip">${icon('spark')}<span><strong>Start anywhere.</strong> First steps is a gentle beginning. Explore both code paths whenever you like.</span></div>${button('branch','Explore both paths','arrow','secondary')}</div>
 <section class="mission-list"><div class="section-title"><h2>All ${PATHS[path].name.toLowerCase()} missions</h2><span>${completed} restored · 10 adventures</span></div><div class="mission-cards">${list.map(level=>`<button data-action="level" data-id="${level.id}" class="mission-card ${p.completed[level.id]?'restored':''}"><span class="level-badge">${p.completed[level.id]?icon('check'):level.id}</span><span><strong>${level.title}</strong><small>${level.concept}</small></span>${icon('right')}</button>`).join('')}</div></section>`);
}
function renderBranch(){shell(`<div class="branch-page"><span class="eyebrow">Two paths. One adventure.</span><h1>Where shall we go?</h1><p>Keep helping the islands with Python or C#.<br>You can switch paths whenever you like.</p><div class="branch-characters">${hero(profiles.current.appearance.suit,profiles.current.appearance.emblem,true)}${robot()}</div><div class="branch-cards">${['python','csharp'].map(key=>`<button class="branch-card ${key}" data-action="path" data-path="${key}"><span class="path-symbol">${key==='python'?'Py':'C#'}</span><h2>${PATHS[key].name}</h2><p>${PATHS[key].intro}</p><span class="text-link">Explore ${PATHS[key].island} ${icon('right')}</span></button>`).join('')}</div>${button('foundations','Back to First steps','map','secondary')}</div>`);}
function openMission(id,variant){
 const sandboxPath=id?.startsWith('sandbox-')?id.slice(8):null;
 const existing=profiles.current.saved[id];config=sandboxPath?sandbox(sandboxPath):challenge(id,variant??existing?.variant??0);
 if(variant!==undefined&&!sandboxPath)config=challenge(id,variant);
 path=config.path;profiles.update(p=>p.lastPath=path);
 saved=existing&&variant===undefined?copy(existing):{variant:config.variant,code:config.path==='foundation'?'':config.starter,blocks:config.path==='foundation'?copy(config.initial??[]):[],hintStage:0,exampleUsed:false,baseline:config.starter??''};
 world=createWorld(config);screen='mission';slot=[];selectedBlock=null;insertAt=null;tape=[];renderMission();save();
 if(path!=='foundation')ensureRuntime().catch(()=>{});
}
function renderMission(){
 const foundation=path==='foundation';
 shell(`<div class="mission-top">${button('back','Islands','back','secondary compact')}<div><span class="eyebrow">${config.id.startsWith('sandbox')?'Playground':`${config.id} · ${PATHS[path].island}`}</span><h1>${esc(config.title)}</h1></div><span class="variant-badge">Adventure ${config.variant+1} / 4</span></div>
 <div class="mission-layout"><section class="world-panel"><div class="world-heading"><span class="live-dot"></span><strong>Your world</strong><span id="world-state">Ready for your ideas</span></div><div id="world" class="world-scene">${worldSvg(world,profiles.current.appearance)}</div><div class="goal-card">${icon('flag')}<div><span class="eyebrow">Our mission</span><strong>${esc(config.task)}</strong><p>${esc(config.goalText)}</p></div>${button('hear','Hear','sound','icon-text')}</div><div class="pip-panel"><span class="pip-face">${robot()}</span><div id="pip-feedback" role="status"><strong>Let’s try it together.</strong><p>${foundation?'Tap a picture to add an instruction.':'Change your code, then see what happens.'}</p></div>${button('hint','Help','help','secondary compact')}</div><div id="hint-area"></div><div id="celebration"></div><details class="command-guide"><summary>${icon('book')} Pip’s command guide</summary>${commandGuide()}</details><div class="world-tools">${button('variant','New adventure','reset','text-button')}<span>Four solvable versions of this mission</span></div></section>
 <section class="editor-panel" aria-label="${foundation?'Instruction builder':'Code editor'}"><div class="editor-heading"><div><span class="language-dot ${path}"></span><strong>${foundation?'Picture instructions':path==='python'?'Python':'C#'}</strong><span class="editor-tag">${foundation?'Tap to build':'Editable source'}</span></div>${button('starter',foundation?'Clear':'Starter','reset','text-button')}</div>
 ${foundation?'<div id="block-editor"></div>':`<div class="code-legend"><span><i class="supplied"></i> Supplied lines</span><span><i class="changed"></i> Your changes</span></div><div class="code-wrap"><pre class="line-gutter" id="line-gutter" aria-hidden="true"></pre><textarea id="code" spellcheck="false" autocorrect="off" autocapitalize="off" autocomplete="off" translate="no" aria-label="Your editable ${path==='python'?'Python':'C#'} code" aria-describedby="editor-instructions" wrap="off" maxlength="32768">${esc(saved.code)}</textarea></div><p id="editor-instructions" class="editor-instructions">Tab adds four spaces. Escape then Tab leaves the editor. Starter code stays available.</p>`}
 <div class="runtime-status ${foundation?'foundation-ready':''}" id="runtime-status" role="status">${foundation?`${icon('check')} Picture instructions ready`:'Preparing your language toolkit…'}</div><div id="runtime-recovery"></div><div class="run-controls">${button('run','Run','play','orange')}${button('stop','Stop','stop','secondary')}${button('reset-world','Reset','reset','secondary')}${button('step','Step','step','secondary','aria-label="Step through game actions"')}</div><p class="step-note">Step runs the program, then steps through its game actions.</p><div class="action-readout" id="action-readout">${icon('code')}<span>Your instructions will appear here.</span></div><details class="output-panel" open><summary>Output <span id="action-count">0 actions</span></summary><pre id="output" aria-label="Program output">Ready when you are.</pre></details>${foundation?`<details class="pseudocode"><summary>See pseudocode</summary><p>Readable instructions for this block builder. This is not executable Python or C#.</p><pre id="pseudocode"></pre></details>`:`<details class="supplied-code"><summary>What code does the Academy supply?</summary><p>The game API and runtime are supplied separately. Only the editable box above is your program. Mint gutter marks show unchanged supplied lines; orange marks show lines changed in this browser. This is an editing aid, not proof of authorship.</p><pre>${path==='python'?'game is supplied by the Academy.\nSee Pip’s command guide for its methods.':'Game is a supplied static C# class.\nSystem, Collections.Generic and Linq are imported.\nSee Pip’s command guide for its methods.'}</pre></details>`}</section></div>`);
 if(foundation)renderBlocks();else bindEditor();renderHints();controls();
}
function commandGuide(){
 if(path==='foundation')return `<p>Tap pictures to add steps. Tap a step, then a picture to replace it. Up/down arrows change the order. “Inside” adds steps inside Repeat, If or Make repair.</p><p>Run tries the whole program. Reset returns the world to its start and keeps your instructions.</p>`;
 const py=path==='python',name=s=>py?`game.${s}`:`Game.${s.replace(/(^|_)(\w)/g,(_,p,c)=>c.toUpperCase())}`;
 const rows=[['move','"right"','Move one square. Also left, up or down.'],['robot','"Pip", 5, '+(py?'True':'true'),'Set name, energy and ready state.'],['supply','6','Send repair supplies.'],['energy','','Read current world power.'],['needed','','Read the power goal.'],['gate',py?'True':'true','Open if there is enough power.'],['sensor','','Read clear or blocked.'],['destination','','Read the building on a parcel.'],['route','"left"','Choose left/right or a named building.'],['count','','Read the number of plants or signals.'],['water','0','Water plant 0. Rows start at 0.'],['light','0','Light signal 0.'],['charge','1','Add one power cell.'],['repair','"bridge"','Repair one place shown in the world.'],['delivery_list','','Get the delivery list.'],['deliver','"tools"','Deliver one listed item.'],['district','','Get a list of places to restore.'],['lift','2, '+(py?'True':'true'),'Move to a floor when powered and ready.'],['store','5','Set world power.'],['collect','','Take one cell from the store.']];
 return `<p>These are the Academy’s supplied game commands. Numbers, loops, choices and functions use real ${py?'Python':'C#'}.</p><table><thead><tr><th>Command</th><th>What happens</th></tr></thead><tbody>${rows.map(([s,args,text])=>`<tr><td><code>${name(s)}(${args})${py?'':';'}</code></td><td>${text}</td></tr>`).join('')}</tbody></table><p>Sensors read the simulated world after your earlier commands. Output from ${py?'print()':'Console.WriteLine()'} appears on a beacon. The world replays the actions your program actually produced.</p>`;
}
function bindEditor(){
 const el=$('#code');el.value=saved.code;updateGutter();
 el.addEventListener('input',()=>{saved.code=el.value;tape=[];tapeIndex=0;save();updateGutter();});
 el.addEventListener('scroll',()=>$('#line-gutter').scrollTop=el.scrollTop);
 el.addEventListener('keydown',e=>{
  if(e.key==='Escape'){readingCode=true;return;}
  if(e.key==='Tab'){
   if(readingCode){readingCode=false;return;}e.preventDefault();const start=el.selectionStart,end=el.selectionEnd;
   if(e.shiftKey){const begin=el.value.lastIndexOf('\n',start-1)+1;if(el.value.slice(begin,begin+4)==='    '){el.setRangeText('',begin,begin+4,'end');el.selectionStart=el.selectionEnd=Math.max(begin,start-4);}}
   else el.setRangeText('    ',start,end,'end');el.dispatchEvent(new Event('input'));return;
  }
  readingCode=false;
  if(e.key==='Enter'){
   e.preventDefault();const start=el.selectionStart,prefix=el.value.slice(0,start).split('\n').at(-1),indent=prefix.match(/^ */)[0]+(/[{:][ ]*$/.test(prefix)?'    ':'');el.setRangeText('\n'+indent,start,el.selectionEnd,'end');el.dispatchEvent(new Event('input'));
  }
 });
}
function updateGutter(){const base=saved.baseline.split('\n');$('#line-gutter').innerHTML=saved.code.split('\n').map((line,i)=>`<span class="${base[i]===line?'supplied':'changed'}">${i+1}</span>`).join('');}
function getSlot(route=slot){let nodes=saved.blocks;for(let i=0;i<route.length;i+=2){const n=nodes[Number(route[i])];n[route[i+1]]??=[];nodes=n[route[i+1]];}return nodes;}
function renderBlocks(){
 const render=(nodes,route=[])=>`<ol class="program-blocks">${nodes.map((node,index)=>{const p=[...route,index],encoded=esc(JSON.stringify(p)),isSelected=JSON.stringify(p)===JSON.stringify(selectedBlock);return `<li><div class="program-block ${isSelected?'selected':''}"><button class="block-label" data-action="select-block" data-route="${encoded}" aria-pressed="${isSelected}">${blockIcon(node)}<span>${esc(BLOCK_LABELS[node.op]??node.op)} ${node.arg!==undefined&&!['repeat','if','set','add','define','gate'].includes(node.op)?esc(node.arg):''}</span></button>${['repeat','if','set','add'].includes(node.op)?`<input type="number" class="block-number" min="0" max="20" value="${node.arg}" data-block-value="${encoded}" aria-label="${esc(BLOCK_LABELS[node.op])} value">`:''}<div class="block-tools"><button data-action="block-up" data-route="${encoded}" aria-label="Move step ${index+1} earlier" ${index===0?'disabled':''}>${icon('up')}</button><button data-action="block-down" data-route="${encoded}" aria-label="Move step ${index+1} later" ${index===nodes.length-1?'disabled':''}>${icon('down')}</button><button data-action="block-remove" data-route="${encoded}" aria-label="Remove step ${index+1}">${icon('close')}</button></div></div>${['repeat','if','ifelse','define'].includes(node.op)?`<div class="block-nest">${render(node.body??[],[...p,'body'])}<button class="insert-slot ${JSON.stringify(slot)===JSON.stringify([...p,'body'])?'chosen':''}" data-action="slot" data-route="${esc(JSON.stringify([...p,'body']))}">${icon('down')} ${node.op==='ifelse'?'If clear':node.op==='define'?'Inside repair':'Inside'}</button>${node.op==='ifelse'?`<span class="otherwise-label">Otherwise</span>${render(node.otherwise??[],[...p,'otherwise'])}<button class="insert-slot ${JSON.stringify(slot)===JSON.stringify([...p,'otherwise'])?'chosen':''}" data-action="slot" data-route="${esc(JSON.stringify([...p,'otherwise']))}">${icon('down')} If blocked</button>`:''}</div>`:''}</li>`;}).join('')}</ol>`;
 $('#block-editor').innerHTML=`<div class="block-palette" aria-label="Instruction pictures">${config.palette.map((n,i)=>`<button data-action="add-block" data-index="${i}" class="palette-block">${blockIcon(n)}<span>${esc(BLOCK_LABELS[n.op]??n.op)}${n.arg!==undefined&&!['ifelse','define','gate'].includes(n.op)?' '+esc(n.arg):''}</span></button>`).join('')}</div><div class="builder-caption"><strong>Your instructions</strong><span>${selectedBlock?'Tap a picture to replace the selected step.':slot.length?'Adding inside this block.':'Tap pictures to add steps.'}</span></div><div class="program-area">${render(saved.blocks)}<button class="insert-slot root-slot ${!slot.length&&!selectedBlock?'chosen':''}" data-action="slot" data-route="[]">${icon('down')} ${saved.blocks.length?'Add at the end':'Start here'}</button></div>`;
 $('#pseudocode').textContent=pseudocode(saved.blocks).join('\n')||'Your instructions will appear here.';
 $('#block-editor').querySelectorAll('[data-block-value]').forEach(el=>el.addEventListener('change',()=>{const r=JSON.parse(el.dataset.blockValue),index=r.pop(),nodes=getSlot(r);nodes[index].arg=Math.max(0,Math.min(20,Number(el.value)||0));save();tape=[];renderBlocks();}));
}
function blockIcon(n){return icon(n.op==='move'?n.arg:n.op==='repeat'?'reset':n.op==='set'||n.op==='add'||n.op==='collect'?'box':n.op==='if'||n.op==='ifelse'?'scan':n.op==='define'||n.op==='call'?'code':n.op==='repair'?'kit':'flag');}
function controls(){const stop=$('[data-action="stop"]'),run=$('[data-action="run"]'),step=$('[data-action="step"]');if(stop)stop.disabled=!(runBusy||loadPromise||autoTimer||tapeIndex<tape.length||speaking);if(run)run.disabled=runBusy;if(step)step.disabled=runBusy;}
async function ensureRuntime(){
 if(path==='foundation')return;if(host?.ready)return;if(loadPromise)return loadPromise;
 const epoch=viewEpoch;
 if(!host)host=new RuntimeHost((message,amount)=>{if(screen!=='mission'||epoch!==viewEpoch)return;const el=$('#runtime-status');if(el)el.innerHTML=`${icon(amount===1?'check':'code')}<span>${esc(message.startsWith('Ready ·')?'Toolkit ready. Your ideas can run.':message)}</span>${amount!==null&&amount<1?`<progress max="1" value="${amount}" aria-label="Language download progress"></progress>`:''}`;},text=>{if(epoch!==viewEpoch)return;const el=$('#output');if(el){if(el.dataset.empty!=='false')el.textContent='';el.dataset.empty='false';el.textContent+=(el.textContent?'\n':'')+text;}});
 const p=host.load(path);loadPromise=p;controls();
 try{await p;if(epoch===viewEpoch)$('#runtime-recovery').innerHTML='';}catch(e){if(epoch===viewEpoch&&screen==='mission')$('#runtime-recovery').innerHTML=`<div class="recovery"><p>The toolkit could not start. Your code is saved.</p>${button('retry-runtime','Retry','reset','secondary')}${button('foundations','First steps','map','secondary')}</div>`;throw e;}finally{if(loadPromise===p)loadPromise=null;controls();}
}
function feedback(text,secondary=''){const el=$('#pip-feedback');if(el)el.innerHTML=`<strong>${esc(text)}</strong>${secondary?`<p>${esc(secondary)}</p>`:''}`;announce(text);}
function drawWorld(){if($('#world'))$('#world').innerHTML=worldSvg(world,profiles.current.appearance);}
async function run(step=false){
 if(runBusy)return;if(step&&tapeIndex<tape.length){advance(true);return;}
 clearTimeout(autoTimer);autoTimer=null;$('#celebration').innerHTML='';world=createWorld(config);drawWorld();tape=[];tapeIndex=0;features=[];runError='';runBusy=true;controls();const epoch=viewEpoch;
 const output=$('#output');output.textContent='';output.dataset.empty='true';feedback('Let’s see what happens.');
 try{
  let result;
  if(path==='foundation')result=runBlocks(saved.blocks,config);
  else {await ensureRuntime();if(epoch!==viewEpoch)return;result=await host.run(saved.code,config);}
  if(epoch!==viewEpoch)return;
  tape=result.actions;features=result.features;runError=result.error??'';runBusy=false;$('#action-count').textContent=`${tape.length} actions`;if(!output.textContent)output.textContent='No printed messages.';
  if(!tape.length)finishRun();else advance(step);controls();
 }catch(e){if(epoch!==viewEpoch)return;runBusy=false;runError=String(e.message||e);showError(runError);profiles.record(config.id,config.variant,{complete:false,goal:false,missing:config.requires},support());controls();}
}
function advance(step){
 if(tapeIndex>=tape.length){finishRun();return;}
 const cmd=tape[tapeIndex++];
 try{applyCommand(world,cmd);}catch(e){runError=e.message;finishRun();return;}
 drawWorld();$('#action-readout').innerHTML=`${icon('code')}<span><strong>${tapeIndex} / ${tape.length}</strong> ${esc(cmd.op)}(${cmd.args.map(x=>esc(JSON.stringify(x))).join(', ')})</span>`;$('#world-state').textContent=`Action ${tapeIndex} of ${tape.length}`;
 if(tapeIndex===tape.length)finishRun();else if(!step)autoTimer=setTimeout(()=>advance(false),motionReduced()?70:480);else feedback('One step at a time.','Tap Step for the next game action.');controls();
}
function showError(error){const e=friendlyError(error,path);if(path!=='foundation')$('#runtime-status').textContent='Paused. Your code is saved.';feedback(e.help);const out=$('#output');out.textContent+=(out.textContent?'\n\n':'')+e.raw;out.parentElement.open=true;$('#world-state').textContent='Ready to try again';}
function finishRun(){
 clearTimeout(autoTimer);autoTimer=null;runBusy=false;
 const result=assess(config,tape,features);if(runError){result.complete=false;showError(runError);}else feedback(config.kind==='sandbox'?'That was your idea in action.':result.feedback,config.kind==='sandbox'?'Change it. Try something new.':result.complete?'The island feels a little brighter.':'');
 const pointsBefore=profiles.current.points;profiles.record(config.id,config.variant,result,support());const earned=profiles.current.points-pointsBefore;updateHeader();
 $('#world-state').textContent=result.complete?'Place restored':config.kind==='sandbox'?'Your ideas in action':'Ready to try again';
 if(result.complete)celebrate(()=>{const n=nextLevel(config.id);nextAfterGame=n;navigate('game',ACTIVITIES[(config.n-1)%ACTIVITIES.length].id);},'Place restored!',`${earned?'+'+earned+' points · ':''}${support()==='independent'?'Your ideas worked!':'A little help. A big adventure.'}`);
 controls();
}
function celebrate(next,title,subtitle){
 let remaining=3,called=false;const el=$('#celebration')??$('.mini-celebration');
 const proceed=()=>{if(called)return;called=true;clearTimeout(autoTimer);autoTimer=null;next();};
 const draw=()=>{if(!el)return;el.innerHTML=`<div class="celebration"><span class="reward-star">${icon('star')}</span><div><strong>${esc(title)}</strong><p>${esc(subtitle)}</p><small>Next adventure in ${remaining}…</small></div><button data-celebrate-next>Next ${icon('right')}</button><button data-celebrate-stay aria-label="Stay here and cancel the automatic transition">Stay</button></div>`;el.querySelector('[data-celebrate-next]').onclick=proceed;el.querySelector('[data-celebrate-stay]').onclick=()=>{clearTimeout(autoTimer);autoTimer=null;el.querySelector('small').textContent='Stay, explore, or use Back.';controls();};};
 const tick=()=>{draw();if(remaining--<=0)proceed();else autoTimer=setTimeout(tick,1000);};tick();announce(title);controls();
}
function renderHints(){
 if(!$('#hint-area'))return;const stage=saved.hintStage;
 if(!stage){$('#hint-area').innerHTML='';return;}
 $('#hint-area').innerHTML=`<div class="hint-card"><div class="hint-title">${icon('lamp')}<strong>Pip’s help · ${stage} / 4</strong></div>${stage===1?`<div class="hint-pictures">${icon('scan')}${icon(config.kind==='garden'?'plant':config.kind==='message'?'signal':'flag')}${icon('arrow')}</div><p>${esc(config.clue)}</p>`:stage===2?`<p>${esc(config.explanation)}</p>`:stage===3?`<p>A beginning to build on:</p><pre>${esc(path==='foundation'?pseudocode(config.partial).join('\n')||'Choose your first instruction.':config.partial)}</pre>${button('partial','Try this start','code','secondary')}`:`<p>This worked example is supplied. Using it is recorded as completion with support.</p><pre>${esc(path==='foundation'?pseudocode(config.example).join('\n'):config.example)}</pre>${button('example','Use example','code','secondary')}`}${stage<4?button('hint','Another clue','help','text-button'):''}</div>`;
 $('#world').classList.add('helped');
}
function renderFun(){shell(`<div class="page-title"><div><span class="eyebrow">A little break, a little adventure</span><h1>Just for fun.</h1><p>Catch, explore, remember and glide. No coding needed.</p></div></div><div class="fun-cards">${ACTIVITIES.map((a,i)=>`<button class="fun-card" data-action="game" data-id="${a.id}"><div class="fun-art art-${i}">${icon(a.icon)}${i===0?icon('star'):''}</div><span class="eyebrow">Adventure break ${i+1}</span><h2>${a.title}</h2><p>${a.task}</p><span class="text-link">Play ${icon('play')}</span></button>`).join('')}</div><p class="quiet">These activities are extra play. They do not count as any of the 30 coding missions.</p>`);}
function renderGame(id){gameId=id;screen='game';shell(`<div class="mini-top">${button('back','Islands','back','secondary compact')}<span>${icon('game')} Adventure break</span></div><section class="mini-shell"><div id="mini-root"></div><div class="mini-celebration"></div></section>`);const epoch=viewEpoch;gameCleanup=mountGame($('#mini-root'),id,{appearance:profiles.current.appearance,reducedMotion:motionReduced(),onComplete:()=>{if(epoch!==viewEpoch)return;const wasRewarded=profiles.current.rewards.includes('activity-'+id);profiles.reward('activity-'+id,20,'activity-'+id);updateHeader();celebrate(()=>{const n=nextAfterGame;nextAfterGame=null;if(n){if(n==='branch'||n==='map')navigate(n);else navigate('mission',n);}else navigate('game',ACTIVITIES[(ACTIVITIES.findIndex(a=>a.id===id)+1)%4].id);},'Adventure complete!',wasRewarded?'A lovely bit of exploring.':'A golden keepsake · +20 reward points');}});}
function renderSandboxChoice(){shell(`<div class="page-title"><div><span class="eyebrow">Make. Wonder. Try again.</span><h1>Pip’s playground.</h1><p>What happens if…? You choose. Every command is here to explore.</p></div></div><div class="sandbox-hero">${robot()}<span>${icon('code')}</span></div><div class="sandbox-choices">${Object.entries(PATHS).map(([key,p])=>`<button class="branch-card" data-action="level" data-id="sandbox-${key}"><span class="path-symbol">${key==='foundation'?icon('box'):key==='python'?'Py':'C#'}</span><h2>${key==='foundation'?'Picture blocks':p.name}</h2><p>${key==='foundation'?'Tap instructions. Make your own little program.':'Write editable code. Watch your ideas happen.'}</p><span class="text-link">Explore ${icon('right')}</span></button>`).join('')}</div><p class="quiet">There are no scores for learning here. Your experiments are saved as practice.</p>`);}
function renderHero(){const p=profiles.current;shell(`<div class="page-title"><div><span class="eyebrow">Every adventure needs you</span><h1>Your kind of hero.</h1><p>Make yourself at home in the Academy.</p></div>${button('players','Switch hero','user','secondary')}</div><div class="hero-layout"><div class="hero-portrait">${hero(p.appearance.suit,p.appearance.emblem,p.appearance.cape)}<span>${esc(p.name)}</span></div><div class="hero-options"><h2>Pick a suit</h2><div class="suit-choices">${[['Orange','#EC7540'],['Teal','#13786E'],['Blue','#586CCA'],['Berry','#AD4B7F']].map(([name,colour])=>`<button style="--suit:${colour}" data-action="suit" data-value="${colour}" aria-pressed="${p.appearance.suit===colour}"><i></i>${name}${p.appearance.suit===colour?icon('check'):''}</button>`).join('')}</div><h2>Your emblem</h2><div class="emblem-choices">${['star','diamond','bolt'].map(x=>`<button data-action="emblem" data-value="${x}" aria-pressed="${p.appearance.emblem===x}">${icon(x==='diamond'?'spark':x==='bolt'?'signal':'star')} ${x}</button>`).join('')}</div><label class="setting"><input type="checkbox" id="cape-setting" ${p.appearance.cape?'checked':''}> Golden cape</label><h2>Your keepsakes</h2><div class="collectibles">${p.collectibles.length?p.collectibles.map(x=>`<span title="${esc(x)}" aria-label="Keepsake ${esc(x)}">${icon(x.startsWith('activity')?'game':'star')}</span>`).join(''):'<p>There is room for your first golden keepsake.</p>'}</div><p class="quiet">Keepsakes and points celebrate playing. Practice records show how a mission was completed.</p></div></div>`);$('#cape-setting').onchange=e=>{profiles.update(p=>p.appearance.cape=e.target.checked);renderHero();};}
function renderAdults(){const p=profiles.current;const statusText=s=>({independent:'Independent',hints:'After hints',example:'With worked example'})[s];shell(`<div class="page-title"><div><span class="eyebrow">For the people cheering them on</span><h1>Room to grow.</h1><p>Settings, local saves and a useful view of each hero’s practice.</p></div>${button('players','Players','user','secondary')}</div><div class="adult-grid"><section class="adult-card"><h2>Comfortable play</h2><label class="setting"><input id="large-setting" type="checkbox" ${p.settings.largeText?'checked':''}> Large text</label><label class="setting"><input id="motion-setting" type="checkbox" ${p.settings.reducedMotion?'checked':''}> Reduce animation</label><p>Device reduced-motion preferences are also respected. Speech starts only after Hear is selected. Use Stop or navigate away to stop speech.</p></section><section class="adult-card"><h2>Keep the adventure safe</h2><p>Named local players are <strong>not online accounts</strong>. Saves stay in this browser on this device and do not automatically synchronise. Clearing browser data can remove them.</p><div class="adult-actions">${button('export','Export backup','download','secondary')}${button('import','Import backup','upload','secondary')}<input type="file" id="backup-input" accept=".json,application/json" hidden></div><p class="small">Export includes every local player. A validated import replaces the local player collection with that backup. Keep the downloaded file somewhere safe.</p></section><section class="adult-card"><h2>Learning and rewards</h2><p>Every mission is available immediately. Foundation, Python and C# progress is separate. Four challenge variants change routes, quantities, arrangements or goals.</p><p>Points and keepsakes reward play. Practice records distinguish independent attempts, attempts after hints, and use of worked examples. A completed mission is not a claim of mastery. Review the child’s explanation and code with them.</p><p>No ads, purchases, compulsory streaks or penalties for mistakes.</p></section><section class="adult-card"><h2>Real code, carefully contained</h2><p>Python uses CPython 3.14.2 in Pyodide 314.0.7. C# 13 uses Roslyn 4.14.0 and the .NET 10.0.13 WebAssembly interpreter, compiling editable source in the browser.</p><p>Each run uses a worker inside an opaque-origin sandbox. Game commands and output are bounded; external network connections and access to saved profiles are blocked. Stop terminates the worker. A five-second execution limit pauses runaway code.</p><p>Step replays game commands, rather than stepping through every source statement. The synchronous game API, standard language features and browser-compatible libraries are available; OS features, extra packages, asynchronous entry points and native libraries are outside this game.</p><p><a href="https://github.com/mightora/hero-academy-codequest/archive/refs/heads/main.zip" class="source-download">Download source &amp; GitHub Pages setup</a></p><details><summary>Downloads and device guidance</summary><p>Language engines load only when their path is opened. Python is approximately 13.54 MB and C# approximately 38.31 MB before transfer compression. Startup depends on device and connection; first C# compilation takes longer than later runs. Stop discards the runtime; returning reloads it from cached downloaded files.</p><p>Current browsers with WebAssembly, module workers, SIMD and Wasm exception handling are required for text-code paths. First steps and mini-games have lighter requirements. Actual iPhone Safari testing has not been performed in this build environment. See the included runtime and test reports before a classroom rollout.</p></details></section></div><section class="adult-card records"><div class="section-title"><div><h2>${esc(p.name)}’s practice</h2><p>${p.practice.length} recorded attempts · ${Object.keys(p.completed).length} missions completed</p></div><div class="record-progress">${Object.keys(PATHS).map(key=>`<span>${PATHS[key].name} <strong>${progress(p,key)}/10</strong></span>`).join('')}</div></div><div class="table-scroll"><table><thead><tr><th>Mission</th><th>Best recorded completion</th><th>Attempts</th><th>Latest practice</th></tr></thead><tbody>${LEVELS.map(l=>{const attempts=p.practice.filter(r=>r.level===l.id),last=attempts.at(-1);return `<tr><th>${l.id} · ${l.title}</th><td>${p.completed[l.id]?statusText(p.completed[l.id].support):'Exploring'}</td><td>${attempts.length}</td><td>${last?`${last.complete?'Complete':last.goal?'Goal reached; concept to practise':'Trying ideas'} · ${statusText(last.support)}`:'—'}</td></tr>`;}).join('')}</tbody></table></div></section>`);
 $('#large-setting').onchange=e=>{profiles.update(p=>p.settings.largeText=e.target.checked);applySettings();};$('#motion-setting').onchange=e=>{profiles.update(p=>p.settings.reducedMotion=e.target.checked);applySettings();};$('#backup-input').onchange=importFile;
}
function showDialog(title,content){dialog.innerHTML=`<div class="dialog-heading"><h2 id="dialog-title">${title}</h2><button data-dialog-close aria-label="Close dialog">${icon('close')}</button></div>${content}`;dialog.showModal();dialog.querySelector('[data-dialog-close]').onclick=()=>dialog.close();}
function players(){save();showDialog('Choose your hero',`<div class="player-list">${profiles.data.players.map(p=>`<button data-player="${esc(p.id)}" aria-pressed="${p.id===profiles.current.id}"><span>${hero(p.appearance.suit,p.appearance.emblem,p.appearance.cape)}</span><div><strong>${esc(p.name)}</strong><small>${p.points} points · ${Object.keys(p.completed).length} places restored</small></div>${p.id===profiles.current.id?icon('check'):icon('right')}</button>`).join('')}</div><form id="new-player"><label for="nickname">A new hero nickname</label><div><input id="nickname" maxlength="24" autocomplete="off" placeholder="e.g. Captain Fern"><button class="orange" type="submit">${icon('user')} Add hero</button></div></form><p class="small quiet">Local players share this device. Each hero keeps their own code, appearance, settings and progress.</p>`);dialog.querySelectorAll('[data-player]').forEach(b=>b.onclick=()=>{profiles.switch(b.dataset.player);dialog.close();saved=null;config=null;path=profiles.current.lastPath;selected=recommend(profiles.current);navigate('map');});dialog.querySelector('#new-player').onsubmit=e=>{e.preventDefault();const name=dialog.querySelector('#nickname').value.trim();if(!name){dialog.querySelector('#nickname').focus();return;}try{profiles.add(name);dialog.close();saved=null;config=null;path='foundation';selected='F1';navigate('map');}catch(error){toast(error.message);}};}
async function importFile(e){const input=e.target;const file=input.files[0];if(!file)return;try{if(file.size>BACKUP_MAX)throw Error('That backup is too large.');const data=validateBackup(await file.text());showDialog('Restore this adventure?',`<p>This backup contains ${data.players.length} heroes:</p><ul>${data.players.map(p=>`<li>${esc(p.name)} · ${p.points} points</li>`).join('')}</ul><p>Restore replaces all current local players with this backup. Export the current adventure first if you want to keep both.</p><button class="orange" id="restore-backup">Restore backup</button>`);dialog.querySelector('#restore-backup').onclick=()=>{profiles.restore(data);dialog.close();saved=null;config=null;path=profiles.current.lastPath;selected=recommend(profiles.current);navigate('map');toast('Adventure restored.');};}catch(error){toast(error.message);}input.value='';}
function downloadBackup(){save();const blob=new Blob([profiles.export()],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`codequest-backup-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);toast('Backup ready. Keep the downloaded file safe.');}
function speak(){if(!('speechSynthesis'in window)){toast('Speech is not available on this browser.');return;}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(config.task+' '+config.goalText);u.lang='en-GB';u.rate=.85;u.pitch=1;const voices=speechSynthesis.getVoices();u.voice=voices.find(v=>v.lang==='en-GB')??voices.find(v=>v.lang.startsWith('en'))??null;speaking=true;u.onend=u.onerror=()=>{speaking=false;controls();};controls();speechSynthesis.speak(u);}

app.addEventListener('click',e=>{
 const b=e.target.closest('[data-action]');if(!b||b.disabled)return;e.preventDefault();const a=b.dataset.action;
 if(['map','back'].includes(a)){nextAfterGame=null;navigate('map');}
 else if(['hero','adults','fun','sandbox','branch'].includes(a)){nextAfterGame=null;navigate(a);}
 else if(a==='foundations'){path='foundation';selected='F1';navigate('map');}
 else if(a==='path'){path=b.dataset.path;profiles.update(p=>p.lastPath=path);selected=LEVELS.find(l=>l.path===path&&!profiles.current.completed[l.id])?.id??LEVELS.find(l=>l.path===path).id;navigate('map');}
 else if(a==='select-mission'){selected=b.dataset.id;renderMap();$(`[data-id="${selected}"]`)?.focus({preventScroll:true});}
 else if(a==='open-selected')navigate('mission',selected);
 else if(a==='level')navigate('mission',b.dataset.id);
 else if(a==='players')players();
 else if(a==='treasure'){const found=profiles.current.collectibles.includes('treasure-'+path);profiles.reward('treasure-'+path,25,'treasure-'+path);toast(found?'This island’s treasure is already in your keepsakes.':'You found a golden keepsake! +25 points');renderMap();}
 else if(a==='game'){nextAfterGame=null;navigate('game',b.dataset.id);}
 else if(a==='run')run(false);
 else if(a==='step')run(true);
 else if(a==='stop'){speaking=false;viewEpoch++;clearTimeout(autoTimer);autoTimer=null;host?.stop();host=null;loadPromise=null;runBusy=false;tape=[];tapeIndex=0;$('#celebration').innerHTML='';if($('#runtime-status'))$('#runtime-status').textContent='Stopped. Your ideas are saved.';feedback('Stopped. Your ideas are saved.');if('speechSynthesis'in window)speechSynthesis.cancel();controls();}
 else if(a==='reset-world'){viewEpoch++;clearTimeout(autoTimer);autoTimer=null;host?.stop();host=null;loadPromise=null;runBusy=false;tape=[];tapeIndex=0;world=createWorld(config);drawWorld();$('#celebration').innerHTML='';$('#action-readout').innerHTML=`${icon('code')}<span>World reset. Your code is still here.</span>`;feedback('A fresh world. Same ideas.');controls();}
 else if(a==='variant'){const id=config.id;save();cleanup();openMission(id,(config.variant+1)%4);}
 else if(a==='starter'){if(path==='foundation')saved.blocks=[];else{saved.code=config.starter;saved.baseline=config.starter;$('#code').value=saved.code;updateGutter();}slot=[];selectedBlock=null;tape=[];save();if(path==='foundation')renderBlocks();toast(path==='foundation'?'Your instruction space is clear.':'Starter restored. Your help record stays with this adventure.');}
 else if(a==='hint'){saved.hintStage=Math.min(4,saved.hintStage+1);save();renderHints();}
 else if(a==='partial'||a==='example'){const v=a==='partial'?config.partial:config.example;if(a==='example')saved.exampleUsed=true;if(path==='foundation')saved.blocks=copy(v);else{saved.code=v;saved.baseline=v;$('#code').value=v;updateGutter();}save();slot=[];selectedBlock=null;tape=[];if(path==='foundation')renderBlocks();feedback(a==='example'?'Try the example. Then make it your own.':'A start to build on.');}
 else if(a==='hear')speak();
 else if(a==='retry-runtime'){host?.stop();host=null;loadPromise=null;ensureRuntime().catch(()=>{});}
 else if(a==='slot'){slot=JSON.parse(b.dataset.route);selectedBlock=null;insertAt=null;renderBlocks();}
 else if(a==='select-block'){selectedBlock=JSON.parse(b.dataset.route);renderBlocks();}
 else if(a==='add-block'){
  const node=copy(config.palette[Number(b.dataset.index)]);if(selectedBlock){const r=[...selectedBlock],i=r.pop();getSlot(r)[i]=node;selectedBlock=null;}else {const nodes=getSlot();if(nodes.length>=80){toast('Pip has lots of steps. Try a repeat or a new program.');return;}if(slot.length>20){toast('Try fewer instructions inside instructions.');return;}nodes.push(node);}save();tape=[];renderBlocks();
 }else if(a.startsWith('block-')){const r=JSON.parse(b.dataset.route),i=r.pop(),nodes=getSlot(r);if(a==='block-remove')nodes.splice(i,1);else if(a==='block-up'&&i>0)[nodes[i],nodes[i-1]]=[nodes[i-1],nodes[i]];else if(a==='block-down'&&i<nodes.length-1)[nodes[i],nodes[i+1]]=[nodes[i+1],nodes[i]];slot=[];selectedBlock=null;save();tape=[];renderBlocks();}
 else if(a==='suit'||a==='emblem'){profiles.update(p=>p.appearance[a==='suit'?'suit':'emblem']=b.dataset.value);renderHero();}
 else if(a==='export')downloadBackup();else if(a==='import')$('#backup-input').click();
});
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
window.addEventListener('pagehide',()=>{save();host?.stop();gameCleanup?.();});
matchMedia('(prefers-reduced-motion: reduce)').addEventListener('change',applySettings);
render();
